import * as T from './vendor/three.module.js';
import {buildAlpineRoof} from './alpine-roof.mjs';
import {createHumanCharacter} from './human-character.mjs';
import {mergeStaticChildren} from './merge-static.mjs';
export const HUT={x:-15,z:-13,entry:{x:-15,z:-8.5},w:8,d:6};
export function buildMountainHut(scene,height,M,label,colliders,navigationTargets,animated){const g=new T.Group();g.position.set(HUT.x,height(HUT.x,HUT.z),HUT.z);g.userData.kind='daniels-summit-hut';g.userData.navigationId='summit-hut';g.userData.door=HUT.entry;scene.add(g);const box=(w,h,d,m,x,y,z)=>{const o=new T.Mesh(new T.BoxGeometry(w,h,d),m);o.position.set(x,y,z);o.castShadow=o.receiveShadow=true;g.add(o);return o;};
 box(8,1.5,6,M.stone,0,.75,0);box(8,1.7,6,M.timber,0,2.35,0);const face=new T.Shape();face.moveTo(-4,3.1);face.lineTo(4,3.1);face.lineTo(0,4.9);face.closePath();for(const side of[-1,1]){const o=new T.Mesh(new T.ShapeGeometry(face),M.timber);o.position.z=side*3.01;if(side<0)o.rotation.y=Math.PI;g.add(o);}buildAlpineRoof(g,M,{halfWidth:4.6,halfDepth:3.65,ridge:5,eave:3.05,rows:12,columns:12,kind:'daniels-hut'});
 for(const x of[-2.5,2.5]){box(1.25,1.15,.1,M.beam,x,2.15,3.04);box(1.05,.96,.08,M.glass,x,2.15,3.12);for(const side of[-1,1]){const shutter=box(.32,1.18,.09,M.cream,x+side*.83,2.15,3.11);for(let j=0;j<4;j++)box(.3,.07,.04,new T.MeshStandardMaterial({color:'#a85542'}),x+side*.83,1.74+j*.24,3.18);}box(.06,1,.1,M.cream,x,2.15,3.2);box(1.05,.06,.1,M.cream,x,2.15,3.2);}
 box(1.05,2.1,.12,M.beam,0,1.12,3.1);box(2.6,.16,1.3,M.timber,0,2.7,3.55);for(const x of[-1.2,1.2])box(.1,2.7,.1,M.beam,x,1.35,4.1);for(let j=0;j<3;j++)box(2.3,.1+j*.1,.35,M.stone,0,(.1+j*.1)/2,3.8-j*.3);box(.6,1.3,.7,M.stone,2.1,4.65,-1);box(.8,.15,.85,M.roof,2.1,5.35,-1);label('Daniel · Tourenhütte',HUT.x,g.position.y+3.4,HUT.z+3.2,4.6);colliders.push({x:HUT.x,z:HUT.z,w:8.2,d:6.2});navigationTargets.push(g);mergeStaticChildren(g);
 const guide=createHumanCharacter('man',{hat:true,hatColor:'#626965',beard:true,backpack:true,glasses:false,jacket:'#a64e3d',hair:'#503c30',hairStyle:'short',pattern:null,pants:'#3a4b57'});guide.g.position.set(-12.3,height(-12.3,-7.4),-7.4);guide.g.userData.kind='guide-daniel';scene.add(guide.g);animated.push(t=>guide.animate({time:t,interacting:true}));return g;}
